css:
/* 波の地面（1周期の非対称波は border-radius では作れない → SVG path） */
.sec{position:relative}
.sec::after{content:''; position:absolute; inset:auto 0 0 0; height:40px;
  background:url(wave.svg) bottom/100% 40px no-repeat}
.kid{position:absolute; right:40px; bottom:-20px; width:150px;
  z-index:2; pointer-events:none}   /* 足元が bottom:0 に来るよう切り抜く */

/* 点線の地面 */
.divider{border-top:1px dotted #d6d6d6; position:relative}
.divider .kid{left:6%; bottom:0; width:130px}
